    actual=nx.Graph();AC=[];BC=[]
    for j in range(len(H)):
        u,w=('pair',j,0),('pair',j,1);AC +=[u,w];actual.add_edge(u,w)
        BC.append(('iso',j));actual.add_node(BC[-1])
    AC +=[('A',u) for u in A];BC +=[('B',u) for u in B]
    actual.add_nodes_from(AC+BC)
